UPDATE merchant_requirement
SET filled_count = CASE
                       WHEN #{increment} > 0 THEN LEAST(filled_count + #{increment}, needed_count)
                       ELSE GREATEST(filled_count + #{increment}, 0)
    END
WHERE job_id = #{jobId}
  AND day_of_week = #{dayOfWeek}
  AND time_slot = #{timeSlot}
